LOAD spatial;

-- Find land removed from each zone (old boundary minus new boundary).
-- Return: zone_name, removed_area where removed_area > 0, ordered by removed_area DESC

setup:
CREATE TABLE zones_old AS SELECT * FROM (VALUES
  ('Zone A', ST_GeomFromText('POLYGON((0 0, 10 0, 10 10, 0 10, 0 0))')),
  ('Zone B', ST_GeomFromText('POLYGON((0 0, 20 0, 20 10, 0 10, 0 0))')),
  ('Zone C', ST_GeomFromText('POLYGON((0 0, 5 0, 5 5, 0 5, 0 0))'))
) t(zone_name, geom);

CREATE TABLE zones_new AS SELECT * FROM (VALUES
  ('Zone A', ST_GeomFromText('POLYGON((0 0, 9 0, 9 10, 0 10, 0 0))')),
  ('Zone B', ST_GeomFromText('POLYGON((0 0, 18 0, 18 10, 0 10, 0 0))')),
  ('Zone C', ST_GeomFromText('POLYGON((0 0, 5 0, 5 5, 0 5, 0 0))'))
) t(zone_name, geom);
